package com.example.examplemod;

import net.neoforged.bus.api.IEventBus;
import net.neoforged.fml.common.Mod;
import net.neoforged.neoforge.capabilities.Capabilities;
import net.neoforged.neoforge.capabilities.RegisterCapabilitiesEvent;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.entity.player.PlayerInteractEvent;

@Mod(ExampleMod.MODID)
public class ExampleMod {
    public static final String MODID = "examplemod";

    public static final net.neoforged.neoforge.registries.DeferredRegister.Items ITEMS =
            net.neoforged.neoforge.registries.DeferredRegister.createItems(MODID);
    public static final net.neoforged.neoforge.registries.DeferredItem<net.minecraft.world.item.Item> EXAMPLE_ITEM =
            ITEMS.registerSimpleItem("battery");

    public ExampleMod(IEventBus modEventBus) {
        ITEMS.register(modEventBus);

        // MOD event bus: registration-time and lifecycle events
        // (registries, EntityAttributeCreationEvent, RegisterPayloadHandlersEvent,
        //  FMLCommonSetupEvent, RegisterCapabilitiesEvent, config events, client reg events).
        modEventBus.addListener(this::onRegisterCapabilities);

        // GAME bus (NeoForge.EVENT_BUS): gameplay events fired during a running game
        // (PlayerInteractEvent, LivingDeathEvent, EntityJoinLevelEvent, TickEvent, ...).
        NeoForge.EVENT_BUS.addListener(this::onRightClickBlock);
    }

    private void onRegisterCapabilities(RegisterCapabilitiesEvent event) {
        event.registerItem(Capabilities.EnergyStorage.ITEM,
                (stack, context) -> new SimpleEnergyItemStorage(stack),
                EXAMPLE_ITEM.get());
    }

    private void onRightClickBlock(PlayerInteractEvent.RightClickBlock event) {
        // gameplay logic; cancel with event.setCanceled(true) if needed
    }

    private static final class SimpleEnergyItemStorage
            implements net.neoforged.neoforge.energy.IEnergyStorage {
        private final net.minecraft.world.item.ItemStack stack;
        SimpleEnergyItemStorage(net.minecraft.world.item.ItemStack stack) { this.stack = stack; }

        @Override public int receiveEnergy(int toReceive, boolean simulate) {
            int stored = stack.getOrDefault(ExampleMod.CHARGE.get(), 0);
            int accepted = Math.min(toReceive, Math.max(0, 10000 - stored));
            if (!simulate && accepted > 0) stack.set(ExampleMod.CHARGE.get(), stored + accepted);
            return accepted;
        }
        @Override public int extractEnergy(int toExtract, boolean simulate) { return 0; }
        @Override public int getEnergyStored() { return stack.getOrDefault(ExampleMod.CHARGE.get(), 0); }
        @Override public int getMaxEnergyStored() { return 10000; }
        @Override public boolean canExtract() { return false; }
        @Override public boolean canReceive() { return true; }
    }

    public static final net.neoforged.neoforge.registries.DeferredHolder<
            net.minecraft.core.component.DataComponentType<?>,
            net.minecraft.core.component.DataComponentType<Integer>> CHARGE =
            net.neoforged.neoforge.registries.DeferredRegister
                    .create(net.minecraft.core.registries.Registries.DATA_COMPONENT_TYPE, MODID)
                    .registerComponent("charge", builder -> builder
                            .persistent(com.mojang.serialization.Codec.INT)
                            .networkSynchronized(net.minecraft.network.codec.ByteBufCodecs.VAR_INT)
                            .build());
}

