import net.minecraftforge.common.capabilities.AutoRegisterCapability;
import net.minecraftforge.common.capabilities.Capability;
import net.minecraftforge.common.capabilities.CapabilityInject;
import net.minecraftforge.common.capabilities.ICapabilitySerializable;
import net.minecraftforge.common.util.LazyOptional;
import net.minecraftforge.event.AttachCapabilitiesEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

@Mod.EventBusSubscriber(modid = ExampleMod.MODID, bus = Mod.EventBusSubscriber.Bus.FORGE)
public class ManaCapability {

    public static final ResourceLocation KEY = new ResourceLocation(ExampleMod.MODID, "mana");
    private static final String ATTACH_FLAG = "examplemod_mana_attached";

    @CapabilityInject(Mana.class)
    public static Capability<Mana> MANA_CAP = null;

    @AutoRegisterCapability
    public interface Mana {
        int get();

        void set(int value);
    }

    public static class ManaImpl implements Mana {
        private int value;

        @Override
        public int get() {
            return value;
        }

        @Override
        public void set(int v) {
            this.value = Math.max(0, v);
        }
    }

    public static class Provider implements ICapabilitySerializable<CompoundTag> {
        private final ManaImpl backend = new ManaImpl();
        private final LazyOptional<Mana> optional = LazyOptional.of(() -> backend);

        @Override
        public <T> LazyOptional<T> getCapability(Capability<T> cap, @Nullable Direction side) {
            return cap == MANA_CAP ? optional.cast() : LazyOptional.empty();
        }

        @Override
        public CompoundTag serializeNBT() {
            CompoundTag tag = new CompoundTag();
            tag.putInt("mana", backend.get());
            return tag;
        }

        @Override
        public void deserializeNBT(CompoundTag tag) {
            backend.set(tag.getInt("mana"));
        }

        public void invalidate() {
            optional.invalidate();
        }
    }

    @SubscribeEvent
    public static void onAttachCapabilities(AttachCapabilitiesEvent<Entity> event) {
        Entity entity = event.getObject();
        if (entity instanceof Player) {
            if (!entity.getPersistentData().getBoolean(ATTACH_FLAG)) {
                event.addCapability(KEY, new Provider());
                entity.getPersistentData().putBoolean(ATTACH_FLAG, true);
            }
        }
    }
}

