class CrateMenu extends AbstractContainerMenu {
    private final ItemStackHandler items;

    public CrateMenu(int windowId, Inventory playerInventory, BlockPos pos) {
        super(ModMenus.CRATE_MENU.get(), windowId);
        BlockEntity be = playerInventory.player.level().getBlockEntity(pos);
        this.items = (be instanceof CrateBlockEntity)
                ? ((CrateBlockEntity) be).getItems()
                : new ItemStackHandler(9);
        this.addSlot(new SlotItemHandler(this.items, 0, 62, 17));
        this.addSlot(new SlotItemHandler(this.items, 1, 80, 17));
        this.addSlot(new SlotItemHandler(this.items, 2, 98, 17));
        this.addSlot(new SlotItemHandler(this.items, 3, 62, 35));
        this.addSlot(new SlotItemHandler(this.items, 4, 80, 35));
        this.addSlot(new SlotItemHandler(this.items, 5, 98, 35));
        this.addSlot(new SlotItemHandler(this.items, 6, 62, 53));
        this.addSlot(new SlotItemHandler(this.items, 7, 80, 53));
        this.addSlot(new SlotItemHandler(this.items, 8, 98, 53));
        for (int row = 0; row < 3; ++row) {
            for (int col = 0; col < 9; ++col) {
                this.addSlot(new Slot(playerInventory, col + row * 9 + 9,
                        8 + col * 18, 84 + row * 18));
            }
        }
    }

    @Override
    public ItemStack quickMoveStack(Player player, int index) {
        return ItemStack.EMPTY;
    }

    @Override
    public boolean stillValid(Player player) {
        return true;
    }

    public ItemStackHandler getItems() {
        return items;
    }
