import net.minecraftforge.data.event.GatherDataEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

@Mod.EventBusSubscriber(modid = ExampleMod.MODID, bus = Mod.EventBusSubscriber.Bus.MOD)
public class ModDataGen {

    @SubscribeEvent
    public static void onGatherData(GatherDataEvent event) {
        PackOutput output = event.getGenerator().getPackOutput();
        CompletableFuture<HolderLookup.Provider> lookupProvider = event.getLookupProvider();
        ExistingFileHelper helper = event.getExistingFileHelper();

        event.getGenerator().addProvider(event.includeClient(),
                new ModItemModels(output, ExampleMod.MODID, helper));
        event.getGenerator().addProvider(event.includeServer(),
                new ModBlockTags(output, lookupProvider, ExampleMod.MODID, helper));
    }

    public static class ModItemModels extends ItemModelProvider {

        public ModItemModels(PackOutput output, String modid, ExistingFileHelper helper) {
            super(output, modid, helper);
        }

        @Override
        protected void registerModels() {
            withExistingParent("crushed_stone", "block/cube_all")
                    .texture("all", "block/crushed_stone");
        }
    }

    public static class ModBlockTags extends BlockTagsProvider {

        public ModBlockTags(PackOutput output,
                            CompletableFuture<HolderLookup.Provider> lookupProvider,
                            String modid, ExistingFileHelper helper) {
            super(output, lookupProvider, modid, helper);
        }

        @Override
        protected void addTags(HolderLookup.Provider provider) {
            tag(BlockTags.MINEABLE_WITH_PICKAXE);
        }
    }
}

