 * There is NO SRG reobfuscation step anymore: `reobfJar` does not exist in NeoGradle 7 /
 * ModDevGradle, and the plain `jar` task output is the final distributable artifact.
 */
tasks {
    named("assemble") {
        dependsOn("jarJar")
    }
}

// Publish tasks should point at the jarJar output when JiJ is used, e.g. for Minotaur:
// modrinth { uploadFile.set(tasks.jarJar.get()) }

plugins {
    id("net.darkhax.curseforgegradle") version "1.1.24"
}

tasks.create<net.darkhax.curseforgegradle.TaskPublishCurseForge>("publishCurseForge") {
    apiToken = providers.gradleProperty("curseforgeToken")
        .orElse(providers.environmentVariable("CURSEFORGE_TOKEN"))
        .orElse("")

    val mainFile = upload(111222, tasks.jar.get())
    mainFile.releaseType = "release"
    mainFile.changelog = providers.environmentVariable("CHANGELOG").orElse("No changelog")
    mainFile.changelogType = "text"
    mainFile.addGameVersion("1.21.1")
    mainFile.addJavaVersion("Java 21")
    mainFile.addModLoader("NeoForge")
}

// publish with: ./gradlew publishCurseForge

