// Key deltas: ForgeGradle->ModDevGradle, Java 17->21, mappings channel block is gone
// (MDG resolves Mojmap automatically), `minecraft 'net.minecraftforge:forge'` becomes
// neoForge { version = ... }.

{
  "root_cause": "fancybattery was compiled against Minecraft 1.20.4. In 1.20.4 Item has no-arg-free constructor chain matching Item$Properties - the Item(Properties) constructor signature changed in 1.20.5/1.21 (Item became constructible only through deferred/Item.Properties with DataComponent support and the constructor byte code changed). The jar on the server calls a constructor descriptor that no longer exists in 1.21.1's Item class, producing NoSuchMethodError at class init.",
  "fix_explanation": "This is a binary-compatibility failure, not a server misconfiguration. Options: (1) obtain a fancybattery build compiled for NeoForge 1.21.1; (2) if you own the source, rebuild against the 1.21.1 MDK and fix any compile errors (Item subclasses now typically register via DeferredRegister and accept Item.Properties); do NOT attempt runtime bytecode patching.",
  "code_patch": "// rebuild target (NeoForge 1.21.1 MDK):\npublic BatteryItem(Properties props) { super(props); }\n// neoforge.mods.toml dependency:\nversionRange = \"[1.21.1]\""
}

{
  "root_cause": "The mod constructor reads DeferredHolder.get() during the CONSTRUCT phase, but registry entries only become available after registry events finish (new registry event system - no 'RegistryEvent.Register' phase gating). Accessing the holder before entries are bound throws 'Registry Object not present'.",
  "fix_explanation": "Move all RegistryObject/DeferredHolder .get() calls out of the mod constructor. Item construction must happen inside the registration supplier; consumers should use the holder lazily (pass the Supplier, or read .get() in gameplay/event code that runs after registration).",
  "code_patch": "// WRONG: constructor-time get()
public ExampleMod(IEventBus modBus) {
    Item wand = WAND_CORE.get(); // throws
}

// RIGHT: lazy
public ExampleMod(IEventBus modBus) {
    ITEMS.register(modBus); // bind registry
}
// ... use WAND_CORE.get() only after registration (e.g. in creative tab supplier, recipes,
// or FMLCommonSetupEvent)."
}

{
  "root_cause": "The mixin's declared method descriptor declares void ('V') as the return type, but the real LivingEntity#hurt(DamageSource, float) returns boolean ('Z'). With NeoForge 1.21.1 running Mojmap at runtime, `method` strings must match the mapped descriptor exactly; the target set is empty and Mixin's defaultRequire=1 turns that into InjectionError.",
  "fix_explanation": "Fix the descriptor to the real signature: hurt(Lnet/minecraft/world/damagesource/DamageSource;F)Z. Also verify the refmap was generated (mixin annotation processor on the compile classpath and `[[mixins]] config = \"examplemod.mixins.json\"` registered in neoforge.mods.toml) so mappings stay correct in production.",
  "code_patch": "@Inject(method = \"hurt(Lnet/minecraft/world/damagesource/DamageSource;F)Z\",\n        at = @At(\"TAIL\"))\nprivate void examplemod$afterHurt(CallbackInfo ci) { ... }\n// if you need the return value: CallbackInfoReturnable<Boolean> cir"
}

{
  "root_cause": "The common code path unconditionally constructs ClientProxy, whose constructor references net.minecraft.client.Minecraft - a client-only class. On a dedicated server (dist DEDICATED_SERVER) the class fails to load with 'invalid dist DEDICATED_SERVER'.",
  "fix_explanation": "Never touch client classes from common code. Remove the ClientProxy construction from the common path and either (a) isolate client logic in classes registered via @Mod.EventBusSubscriber(value = Dist.CLIENT) or a second @Mod entry point with dist = Dist.CLIENT, or (b) guard with FMLEnvironment.dist checks at the call boundary. Runtime-guarded lazy loading only helps if the client class is not referenced in the loaded code path at all.",
  "code_patch": "// common
public ExampleMod(IEventBus modBus) {
    // no client construction here
}

// client-only
@Mod(value = ExampleMod.MODID, dist = Dist.CLIENT)
public class ExampleModClient { ... }"
}

{
  "root_cause": "The handler class subscribes a GAME-bus event (EntityJoinLevelEvent, a gameplay event) on the MOD event bus. NeoForge validates bus/event pairing at load: events that do not implement IModBusEvent are rejected on the mod bus.",
  "fix_explanation": "Either drop the `bus = Bus.MOD` so the class lands on the game bus (default), or keep Bus.MOD only for lifecycle/registration events (FMLCommonSetupEvent, RegisterPayloadHandlersEvent, EntityAttributeCreationEvent, ...). Split classes if you subscribe to both kinds.",
  "code_patch": "// game bus
@Mod.EventBusSubscriber(modid = ExampleMod.MODID)  // default GAME
public class JoinHandlers {
    @SubscribeEvent
    public static void onJoin(EntityJoinLevelEvent event) { ... }
}"
}

{
  "root_cause": "The mod jar was compiled with Java 21 (class file 65) but the server JVM is Java 17 (class file 61). NeoForge 21.1.x itself targets Java 21, so the environment JVM is wrong for both the loader and the mod.",
  "fix_explanation": "Run the server (and the client launcher profile) with Java 21+. This is one of the rare cases where 'update your Java' IS the correct fix: NeoForge 1.21.1 hard-requires Java 21 (class file 65).",
  "code_patch": "# start.sh\nexec /usr/lib/jvm/java-21-openjdk/bin/java @user_jvm_args.txt -jar neoforge.jar nogui\n// build.gradle.kts keeps sources on 21:\njava { toolchain { languageVersion = JavaLanguageVersion.of(21) } }"
}

{
  "root_cause": "The RightClickItem handler dereferences event.getItemStack() without a null check. In NeoForge 1.21.1 PlayerInteractEvent.RightClickItem#getItemStack() can be null when the interaction is triggered with an empty hand.",
  "fix_explanation": "Guard the handler: fetch the stack once, check for null/EMPTY before any dereference, and early-return so the event is left untouched for vanilla processing.",
  "code_patch": "@SubscribeEvent
public static void onRightClick(PlayerInteractEvent.RightClickItem event) {
    ItemStack stack = event.getItemStack();
    if (stack == null || stack.isEmpty() || !(stack.getItem() instanceof WandItem)) return;
    // safe to use stack
}"
}

{
  "root_cause": "A DataComponentType was used on ItemStacks but its DeferredRegister was never bound to the mod event bus (or the registration supplier returned null), so the component exists in memory during play but is not present in the built-in registry when ItemStack.save encodes the stack. Unregistered components cannot be serialized.",
  "fix_explanation": "Ensure the DataComponentType DeferredRegister is created over Registries.DATA_COMPONENT_TYPE, supplies a fully built type (persistent + networkSynchronized codecs), and that `.register(modEventBus)` is called in the mod constructor. Then verify the component is registered before any world loads.",
  "code_patch": "public ExampleMod(IEventBus modEventBus) {
    DATA_COMPONENTS.register(modEventBus); // was missing
}

DATA_COMPONENTS.registerComponent("charge",
        builder -> builder.persistent(Codec.INT)
                .networkSynchronized(ByteBufCodecs.VAR_INT)
                .build());"
}

{
  "root_cause": "The mod is a straight jar copy from Forge 1.20.1: its TickHandlers class still imports net.minecraftforge.event.TickEvent$PlayerTickEvent. On NeoForge 21.1.x the entire net.minecraftforge namespace is absent (packages are net.neoforged.*), so the class cannot be linked.",
  "fix_explanation": "Recompile the mod against the NeoForge 1.21.1 MDK. Replace the legacy tick event with net.neoforged.neoforge.event.tick.PlayerTickEvent (Pre/Post split) and update every other net.minecraftforge import to its net.neoforged equivalent.",
  "code_patch": "@Mod.EventBusSubscriber(modid = ExampleMod.MODID)
public class TickHandlers {
    @SubscribeEvent
    public static void onPlayerTick(PlayerTickEvent.Post event) {
        // event.getEntity()
    }
}"
}

{
  "root_cause": "The same registry name is registered twice. Typical causes: (1) the mod calls its registration method manually in addition to DeferredRegister binding, (2) two DeferredRegister instances with the same modid register colliding names, or (3) a StaticInit-time call duplicated the register() invocation.",
  "fix_explanation": "Audit the registration path: registration must go through exactly ONE DeferredRegister per registry type, bound once via `.register(modEventBus)`. Remove direct register calls and ensure unique names within the modid.",
  "code_patch": "// single registration point
public static final DeferredRegister.Items ITEMS = DeferredRegister.createItems(MODID);
public static final DeferredItem<Item> EXAMPLE_ITEM = ITEMS.registerSimpleItem("example_item");

public ExampleMod(IEventBus modBus) {
    ITEMS.register(modBus); // exactly once, never call ModItems.register() manually
}"
}

{
  "root_cause": "The payload handler executed game logic directly on the network thread. NeoForge payload handlers run on the network thread unless you move work onto the main thread; world/level mutations are main-thread-only.",
  "fix_explanation": "Wrap the game logic in context.enqueueWork(...) (IPayloadContext) so it is scheduled on the server main thread; read-only payload field access may stay on the network thread.",
  "code_patch": "registrar.playToServer(UseWandPayload.TYPE, UseWandPayload.CODEC, (payload, context) ->\n        context.enqueueWork(() -> {\n            ServerPlayer player = (ServerPlayer) context.player();\n            // safe: server thread\n        }));"
}

{
  "root_cause": "The block entity was half-migrated: tick code still resolves the item handler through the old LazyOptional/ForgeCapabilities path that NeoForge removed, so the lookup returns null and the NPE follows. On NeoForge 1.21.1 capability providers are registered centrally with RegisterCapabilitiesEvent and queried through level.getCapability(...).",
  "fix_explanation": "Register the BE capability in RegisterCapabilitiesEvent (Capabilities.ItemHandler.BLOCK + provider), then query with level.getCapability(Capabilities.ItemHandler.BLOCK, worldPosition, side) and handle the @Nullable return; delete all LazyOptional code.",
  "code_patch": "// registration (MOD bus)
event.registerBlockEntity(Capabilities.ItemHandler.BLOCK, STORAGE.get(),
        (be, side) -> be.handler);

// query
IItemHandler h = level.getCapability(Capabilities.ItemHandler.BLOCK, worldPosition, null);
if (h != null) { ... }"
}

{
  "root_cause": "A client-only vanilla target (net.minecraft.client.gui.Gui) is listed in the COMMON `mixins` section of the config. On a dedicated server those classes never load, so Mixin cannot find the target class and the apply fails fatally.",
  "fix_explanation": "Move the mixin class into the `client` section of mixin.examplemod.json (and into a client-only mixin package). The `client` section is applied only when the client environment is present.",
  "code_patch": "{
  "package": "com.example.examplemod.mixin",
  "mixins": [ "PlayerMixin" ],
  "client": [ "client.GuiMixin" ],
  "injectors": { "defaultRequire": 1 }
}"
}

{
  "root_cause": "FML injects only a fixed set of constructor parameter types: (), (IEventBus), (ModContainer), or (IEventBus, ModContainer). A ModConfigSpec parameter is not an injectable type, so constructor lookup fails with NoSuchMethodException.",
  "fix_explanation": "Change the constructor to the supported (IEventBus modEventBus, ModContainer modContainer) form and register the config via modContainer.registerConfig(...).",
  "code_patch": "public ExampleMod(IEventBus modEventBus, ModContainer modContainer) {\n    modContainer.registerConfig(ModConfig.Type.COMMON, Config.SPEC);\n}"
}

{
  "root_cause": "During construction mods load in parallel. examplemod's static initializer touches JEI's classes (expecting JEI's registry entries to be present), but JEI's own construction may not have completed - a cross-mod construction-order dependency. Registry holders are only guaranteed after registration events, and other mods' singletons are not guaranteed during CONSTRUCT.",
  "fix_explanation": "Remove cross-mod access from static init/construction. Defer integration to FMLCommonSetupEvent (enqueueWork) or later lifecycle points; for JEI specifically, use its plugin API which loads after mod setup, not during mod construction.",
  "code_patch": "@Mod.EventBusSubscriber(modid = ExampleMod.MODID, bus = Mod.EventBusSubscriber.Bus.MOD)
public final class JeiBridge {
    @SubscribeEvent
    public static void onCommonSetup(FMLCommonSetupEvent event) {
        event.enqueueWork(() -> JeiBridge.init());
    }
    private static void init() { ... }
}"
}

{
  "root_cause": "The JEI plugin is registered through Java's ServiceLoader: META-INF/services/mezz.jei.api.IModPlugin must list the FQCN of the provider class. The service file contains a misspelled class name (MyJeiPlguin), so ClassNotFound aborts service construction.",
  "fix_explanation": "Correct the FQCN inside the service file (one fully-qualified class name per line) and make sure the class actually implements mezz.jei.api.IModPlugin with a public no-arg constructor.",
  "code_patch": "# META-INF/services/mezz.jei.api.IModPlugin
com.example.MyJeiPlugin

// class
public final class MyJeiPlugin implements IModPlugin {
    @Override public ResourceLocation getPluginUid() {
        return ResourceLocation.fromNamespaceAndPath("examplemod", "main");
    }
}"
}

package com.example.examplemod;

import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.player.Player;

public class MystAdvancementTrigger {
    public static final ResourceLocation ADVANCEMENT_ID =
            new ResourceLocation("examplemod", "myst_master");

    public static void grant(Player player) {
        if (player.level().isClientSide()) return;
        if (!(player instanceof ServerPlayer sp)) return;
        var adv = sp.server.getAdvancements().getAdvancement(ADVANCEMENT_ID);
        if (adv != null) {
            sp.getAdvancements().award(adv, "granted");
        }
    }
}

package com.example.examplemod.command;

import com.mojang.brigadier.CommandDispatcher;
import com.mojang.brigadier.arguments.IntegerArgumentType;
import com.mojang.brigadier.builder.LiteralArgumentBuilder;
import net.minecraft.commands.CommandSourceStack;
import net.minecraft.commands.Commands;
import net.minecraft.network.chat.Component;

public class ModCommands {
    public static void register(CommandDispatcher<CommandSourceStack> dispatcher) {
        LiteralArgumentBuilder<CommandSourceStack> cmd = Commands.literal("myst")
                .requires(src -> src.hasPermission(2))
                .then(Commands.argument("charge", IntegerArgumentType.integer(1, 100000))
                        .executes(ctx -> {
                            int v = IntegerArgumentType.getInteger(ctx, "charge");
                            ctx.getSource().sendSuccess(
                                    () -> Component.literal("charge set: " + v),
                                    false);
                            return Command.SINGLE_SUCCESS;
                        }));
        dispatcher.register(cmd);
    }

    private static final class Command {
        static final int SINGLE_SUCCESS = 1;
    }
}

