package com.example.examplemod;

import net.minecraftforge.event.TickEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

@Mod.EventBusSubscriber(modid = "examplemod")
public class TickHandlers {
    public static int playerTicks;
    public static int serverTicks;

    // Pre AND Post both fire on Forge: guard the phase or logic doubles
    @SubscribeEvent
    public static void onPlayerTick(TickEvent.PlayerTickEvent event) {
        if (event.phase != TickEvent.Phase.END) return;
        playerTicks++;
    }

    @SubscribeEvent
    public static void onServerTick(TickEvent.ServerTickEvent event) {
        if (event.phase != TickEvent.Phase.END) return;
        serverTicks++;
    }
}

package com.example.examplemod;

import java.util.HashSet;
import java.util.Set;
import net.minecraftforge.event.TagsUpdatedEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

@Mod.EventBusSubscriber(modid = "examplemod")
public class DatapackSync {
    public static final Set<String> KNOWN_TAGS = new HashSet<>();

    @SubscribeEvent
    public static void onTags(TagsUpdatedEvent event) {
        if (!event.shouldUpdateStaticData()) return;
        KNOWN_TAGS.clear();
        event.getTags().keySet().stream()
                .limit(1000)
                .forEach(k -> KNOWN_TAGS.add(k.toString()));
    }
}

package com.example.examplemod;

import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.fml.event.lifecycle.FMLCommonSetupEvent;

@Mod.EventBusSubscriber(modid = "examplemod", bus = Mod.EventBusSubscriber.Bus.MOD)
public class LifecycleHooks {
    private static boolean setupDone;
    public static int setupCount;

    // common setup runs once per side; idempotency is required
    @SubscribeEvent
    public static void onCommonSetup(FMLCommonSetupEvent event) {
        if (setupDone) return;
        setupDone = true;
        setupCount++;
    }
}

package com.example.examplemod;

import net.minecraft.world.level.Level;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

@Mod.EventBusSubscriber(modid = "examplemod")
public class WorldTickHook {
    public static int overworldTicks;

    // world ticks fire PER DIMENSION: gate to overworld + one phase
    @SubscribeEvent
    public static void onLevelTick(TickEvent.LevelTickEvent event) {
        if (event.level.dimension() != Level.OVERWORLD) return;
        if (event.phase != TickEvent.Phase.END) return;
        overworldTicks++;
    }
}

package com.example.examplemod;

import net.minecraftforge.event.entity.living.LivingSpawnEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

@Mod.EventBusSubscriber(modid = "examplemod")
public class SpawnerHook {
    // 1-in-20 suppression rule (deterministic, testable)
    @SubscribeEvent
    public static void onCheckSpawn(LivingSpawnEvent.CheckSpawn event) {
        if (event.getEntity().level().getGameTime() % 20 == 0) {
            event.setCanceled(true);
        }
    }
}

