package com.example.examplemod.worldgen;

public class OreVeinPlacer {
    public static int blocksForVein(int baseSize, float luckFactor) {
        float f = Math.max(-0.5f, Math.min(0.5f, luckFactor));
        int size = Math.round(baseSize * (1 + f));
        return Math.max(1, size);
    }
}

package com.example.examplemod.worldgen;

public class SeedReproducibility {
    // worldgen must be seed-reproducible: never Math.random() here
    public static long featureSeed(long worldSeed, int x, int z, int salt) {
        return worldSeed ^ (x * 341873128712L + z * 132897987541L)
                ^ (salt * 1163783969L);
    }
}

package com.example.examplemod.gameplay;

public class CropGrowthRule {
    // real crops hook randomTick(BlockState, ServerLevel, BlockPos, RandomSource)
    public static int ticksToGrow(int lightLevel, boolean hydrated) {
        if (lightLevel < 9) return -1;
        int base = 400;
        return hydrated ? base / 2 : base;
    }
}

package com.example.examplemod.gameplay;

public class MobSpawnRule {
    public static boolean canSpawn(int lightLevel, String dimension, int packSize) {
        if (lightLevel > 7) return false;
        if (!"minecraft:overworld".equals(dimension)) return false;
        return packSize >= 1 && packSize <= 4;
    }
}

package com.example.examplemod.gameplay;

public class WorldBorderClamp {
    public static int[] clampToWorld(int x, int z, int border) {
        if (border <= 0) return new int[]{0, 0};
        return new int[]{
                Math.max(-border, Math.min(border, x)),
                Math.max(-border, Math.min(border, z))
        };
    }
}

package com.example.examplemod.gameplay;

public class DayNightGate {
    // night window: [13000, 23000) of the 24000-tick day
    public static boolean isNight(long dayTime) {
        long t = ((dayTime % 24000) + 24000) % 24000;
        return t >= 13000 && t < 23000;
    }
}

package com.example.examplemod.gameplay;

public class WeatherGate {
    public static boolean thunderActive(boolean raining, boolean thundering,
                                        boolean isDirty) {
        // isDirty intentionally ignored: kept for API stability
        return raining && thundering;
    }
}

package com.example.examplemod.gameplay;

public class StructurePlacementRule {
    // vanilla semantics: one structure candidate per spacing-grid cell,
    // offset jitter bounded by separation
    public static boolean spawnsHere(int chunkX, int chunkZ, long seed,
                                     int spacing, int separation) {
        int rx = Math.floorDiv(chunkX, Math.max(1, spacing));
        int rz = Math.floorDiv(chunkZ, Math.max(1, spacing));
        long h = Math.abs(Long.hashCode(
                seed ^ rx * 341873128712L ^ rz * 132897987541L));
        int offX = (int) (h % Math.max(1, spacing - separation));
        int offZ = (int) ((h / 7) % Math.max(1, spacing - separation));
        return (chunkX - rx * spacing) == offX
                && (chunkZ - rz * spacing) == offZ;
    }
}

