package com.example.examplemod.block.entity;

import net.minecraft.core.BlockPos;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;

public class CrusherBlockEntity extends BlockEntity {
    private int progress;
    private boolean hasInput;

    public CrusherBlockEntity(BlockPos pos, BlockState state) {
        super(null, pos, state);
    }

    public int getProgress() { return progress; }

    public boolean isRunning() { return hasInput; }

    public static void serverTick(Level level, BlockPos pos, BlockState state,
                                  CrusherBlockEntity be) {
        if (level.isClientSide) return;
        if (be.hasInput) {
            be.progress++;
            if (be.progress >= 200) {
                be.progress = 0;
            }
        }
    }

    @Override
    protected void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
        super.loadAdditional(tag, registries);
        this.progress = tag.getInt("progress");
        this.hasInput = tag.getBoolean("hasInput");
    }

    @Override
    protected void saveAdditional(CompoundTag tag, HolderLookup.Provider registries) {
        super.saveAdditional(tag, registries);
        tag.putInt("progress", this.progress);
        tag.putBoolean("hasInput", this.hasInput);
    }
}

