public class PriceFormatScreen extends Screen {
    public PriceFormatScreen() {
        super(Component.literal("Prices"));
    }

    public static String group(int n) {
        String s = Integer.toString(n);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            if (i > 0 && (s.length() - i) % 3 == 0) sb.append(',');
            sb.append(s.charAt(i));
        }
        return sb.toString();
    }

    public static String formatPrice(int amount) {
        int gold = amount / 10000;
        int silver = (amount % 10000) / 100;
        return group(gold) + "g " + String.format("%02d", silver) + "s";
    }

    @Override
    public void render(GuiGraphics g, int mouseX, int mouseY, float partialTick) {
        renderBackground(g, mouseX, mouseY, partialTick);
        g.drawCenteredString(font, "total: " + formatPrice(123456),
                width / 2, height / 2, 0xFFFFFF);
        super.render(g, mouseX, mouseY, partialTick);
    }
}

