public class CoolerItem extends Item {
    public CoolerItem(Properties props) { super(props); }

    // getShareTag/readShareTag were removed in 1.20.5+. Any component that declares a
    // networkSynchronized codec is synced to the client automatically - no manual tag
    // projection is needed. Read the component directly on both sides:
    public int getTemp(ItemStack stack) {
        return stack.getOrDefault(ExampleMod.TEMPERATURE.get(), 0);
    }
}

class ExampleMod {
    public static final String MODID = "examplemod";

    public static final DeferredRegister<DataComponentType<?>> DATA_COMPONENTS =
            DeferredRegister.create(Registries.DATA_COMPONENT_TYPE, MODID);

    public static final DeferredHolder<DataComponentType<?>, DataComponentType<Integer>> TEMPERATURE =
            DATA_COMPONENTS.registerComponent("temperature",
                    builder -> builder
                            .persistent(Codec.INT)
                            .networkSynchronized(ByteBufCodecs.VAR_INT)
                            .build());

    public ExampleMod(IEventBus modBus) {
        DATA_COMPONENTS.register(modBus);
    }
}

