// NeoForge 1.21.1
package com.example.examplemod;

import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.NbtOps;
import net.minecraft.nbt.Tag;
import net.minecraft.world.item.ItemStack;
import com.mojang.serialization.Dynamic;
import com.mojang.serialization.DynamicOps;

public final class StackIo {

    // ItemStack.save(Tag) / ItemStack.of(Tag) were removed in 1.20.5.
    // Serialization now goes through ItemStack.CODEC and REQUIRES registry access
    // (HolderLookup.Provider), e.g. from a Level, a ServerLevel.registryAccess(),
    // or Minecraft.getInstance().level.registryAccess().
    public static CompoundTag save(ItemStack stack, HolderLookup.Provider registries) {
        Tag encoded = ItemStack.CODEC
                .encodeStart((DynamicOps<Tag>) registries.createSerializationContext(NbtOps.INSTANCE), stack)
                .getOrThrow();
        return (CompoundTag) encoded;
    }

    public static ItemStack load(CompoundTag tag, HolderLookup.Provider registries) {
        return ItemStack.CODEC
                .parse((DynamicOps<Tag>) registries.createSerializationContext(NbtOps.INSTANCE), tag)
                .resultOrPartial(s -> { throw new IllegalStateException("Bad stack: " + s); })
                .orElse(ItemStack.EMPTY);
    }
}

