import io.netty.buffer.ByteBuf;
import java.util.regex.Pattern;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.resources.ResourceLocation;

public record GiveItemRequestPayload(String itemId, int count)
        implements CustomPacketPayload {

    private static final Pattern ID = Pattern.compile("[a-z0-9_]+:[a-z0-9_/]+");

    public static final Type<GiveItemRequestPayload> TYPE =
            new Type<>(ResourceLocation.fromNamespaceAndPath(
                    "examplemod", "give_item_request"));

    public static final StreamCodec<ByteBuf, GiveItemRequestPayload> STREAM_CODEC =
            StreamCodec.composite(
                    ByteBufCodecs.STRING_UTF8, GiveItemRequestPayload::itemId,
                    ByteBufCodecs.VAR_INT, GiveItemRequestPayload::count,
                    GiveItemRequestPayload::new);

    @Override
    public Type<? extends CustomPacketPayload> type() {
        return TYPE;
    }

    // never trust the client: validate format, bounds, permission
    public static boolean validateServer(GiveItemRequestPayload p,
                                         boolean playerHasPermission) {
        if (p.count <= 0 || p.count > 64) {
            return false; // stack-size bounds
        }
        if (p.itemId == null || !ID.matcher(p.itemId).matches()) {
            return false; // id format
        }
        return playerHasPermission; // server-side permission source
    }
}

