public record ChunkQueryPayload(int chunkX, int chunkZ)
        implements CustomPacketPayload {

    public static final Type<ChunkQueryPayload> TYPE =
            new Type<>(ResourceLocation.fromNamespaceAndPath(
                    "examplemod", "chunk_query"));

    public static final StreamCodec<ByteBuf, ChunkQueryPayload> STREAM_CODEC =
            StreamCodec.composite(
                    ByteBufCodecs.VAR_INT, ChunkQueryPayload::chunkX,
                    ByteBufCodecs.VAR_INT, ChunkQueryPayload::chunkZ,
                    ChunkQueryPayload::new);

    @Override
    public Type<? extends CustomPacketPayload> type() {
        return TYPE;
    }

    // packed key: high 32 bits chunkX, low 32 chunkZ (sign-safe mask)
    public static long packKey(int chunkX, int chunkZ) {
        return ((long) chunkX << 32) ^ (chunkZ & 0xffffffffL);
    }

    public static boolean isChunkLoaded(int chunkX, int chunkZ,
                                        Set<Long> loadedKeys) {
        return loadedKeys.contains(packKey(chunkX, chunkZ));
    }
}

