import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.TooltipFlag;
import net.minecraft.world.level.Level;

public class BatteryItem extends Item {
    public static final int MAX_ENERGY = 100000;

    public BatteryItem(Properties properties) {
        super(properties.stacksTo(1).durability(MAX_ENERGY));
    }

    public static int getEnergy(ItemStack stack) {
        CompoundTag tag = stack.getOrCreateTag();
        return tag.contains("Energy") ? tag.getInt("Energy") : 0;
    }

    public static void setEnergy(ItemStack stack, int energy) {
        CompoundTag tag = stack.getOrCreateTag();
        tag.putInt("Energy", Math.min(MAX_ENERGY, Math.max(0, energy)));
    }

    public boolean isBarVisible(ItemStack stack) {
        return true;
    }

    public int getBarWidth(ItemStack stack) {
        return Math.round(13.0F * getEnergy(stack) / (float) MAX_ENERGY);
    }

    @Override
    public void appendHoverText(ItemStack stack, Level level, List<Component> tooltip, TooltipFlag flag) {
        tooltip.add(Component.literal("Energy: " + getEnergy(stack) + "/" + MAX_ENERGY));
    }
}

