package com.example.examplemod.client.render;

import net.minecraft.util.Mth;

public class SpinMath {
    public static float continuousAngle(long gameTime, float partialTick,
                                        float degreesPerTick) {
        float total = (gameTime + partialTick) * degreesPerTick;
        return Mth.positiveModulo(total, 360.0f);
    }

    public static float easedProgress(float t) {
        float c = Mth.clamp(t, 0.0f, 1.0f);
        return c * c * (3.0f - 2.0f * c);
    }
}

package com.example.examplemod.client.render;

import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.blockentity.BlockEntityRenderer;
import net.minecraft.client.renderer.blockentity.BlockEntityRendererProvider;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.util.Mth;
import net.minecraft.world.level.block.Blocks;

import com.mojang.blaze3d.vertex.PoseStack;
import com.example.examplemod.block.entity.FanBlockEntity;

public class FanBER implements BlockEntityRenderer<FanBlockEntity> {
    private final BlockEntityRendererProvider.Context ctx;

    public FanBER(BlockEntityRendererProvider.Context ctx) {
        this.ctx = ctx;
    }

    @Override
    public void render(FanBlockEntity be, float partialTick, PoseStack pose,
                       MultiBufferSource buffers, int light, int overlay) {
        long gameTime = be.getLevel() != null ? be.getLevel().getGameTime() : 0;
        float ramp = Mth.clamp(be.getSpeedLevel() / 3.0f, 0.0f, 1.0f);
        float degPerTick = Mth.lerp(ramp, 5.0f, 60.0f);
        float base = SpinMath.continuousAngle(gameTime, partialTick, degPerTick);
        for (int i = 0; i < 4; i++) {
            double a = Math.toRadians(base + i * 90.0f);
            pose.pushPose();
            pose.translate(0.5 + Math.cos(a) * 0.45, 0.85,
                    0.5 + Math.sin(a) * 0.45);
            pose.scale(0.08f, 0.08f, 0.08f);
            ctx.getBlockRenderDispatcher().getBlockRenderer().renderSingleBlock(
                    Blocks.IRON_BLOCK.defaultBlockState(), pose, buffers,
                    light, OverlayTexture.NO_OVERLAY);
            pose.popPose();
        }
    }
}

package com.example.examplemod.client.render;

import net.minecraft.util.Mth;

public class InterpBuffer {
    private double prev;
    private double cur;

    private InterpBuffer(double initial) {
        this.prev = initial;
        this.cur = initial;
    }

    public static InterpBuffer create(double initial) {
        return new InterpBuffer(initial);
    }

    // called on the client tick thread; render thread reads valueAt.
    // volatile is NOT sufficient: two fields must flip together - a torn
    // pair would lerp across the wrong snapshot. Acceptable here because
    // the worst case is one frame of stale interpolation.
    public void push(double v) {
        prev = cur;
        cur = v;
    }

    public double valueAt(float partialTick) {
        return Mth.lerp(partialTick, prev, cur);
    }

    public boolean isChanged() {
        return prev != cur;
    }
}

package com.example.examplemod.client.render;

import com.mojang.math.Axis;
import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.blockentity.BlockEntityRenderer;
import net.minecraft.client.renderer.blockentity.BlockEntityRendererProvider;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.world.level.block.Blocks;

import com.mojang.blaze3d.vertex.PoseStack;
import com.example.examplemod.block.entity.DoorSwingBlockEntity;

public class DoorSwingBER implements BlockEntityRenderer<DoorSwingBlockEntity> {
    private final BlockEntityRendererProvider.Context ctx;

    public DoorSwingBER(BlockEntityRendererProvider.Context ctx) {
        this.ctx = ctx;
    }

    @Override
    public void render(DoorSwingBlockEntity be, float partialTick, PoseStack pose,
                       MultiBufferSource buffers, int light, int overlay) {
        float eased = SpinMath.easedProgress(be.getOpenAmount());
        pose.pushPose();
        // hinge at x=0.15: translate to hinge, rotate, translate back
        pose.translate(0.15, 0.0, 0.5);
        pose.mulPose(Axis.YP.rotationDegrees(eased * 90.0f));
        pose.translate(-0.15, 0.0, -0.5);
        pose.translate(0.5, 0.0, 0.5);
        pose.scale(0.9f, 1.0f, 0.12f);
        ctx.getBlockRenderDispatcher().getBlockRenderer().renderSingleBlock(
                Blocks.OAK_PLANKS.defaultBlockState(), pose, buffers, light,
                OverlayTexture.NO_OVERLAY);
        pose.popPose();
    }
}

package com.example.examplemod.client.render;

public class FovEffectDoc {
    public static double warpedFov(double baseFov, float effectLevel) {
        double c = Math.max(0, Math.min(1, effectLevel));
        return baseFov / (1.0 + 0.4 * c);
    }

    public static boolean reversibilityCheck(double fov) {
        // clamping makes the warp asymmetric: negative levels clamp to 0
        return warpedFov(warpedFov(fov, 1.0f), -1.0f) != fov;
    }
}

package com.example.examplemod.client.render;

import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.blockentity.BlockEntityRenderer;
import net.minecraft.client.renderer.blockentity.BlockEntityRendererProvider;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.world.level.block.Blocks;

import com.mojang.blaze3d.vertex.PoseStack;
import com.example.examplemod.block.entity.AmbientBlockEntity;

public class AmbientBER implements BlockEntityRenderer<AmbientBlockEntity> {
    private final BlockEntityRendererProvider.Context ctx;

    public AmbientBER(BlockEntityRendererProvider.Context ctx) {
        this.ctx = ctx;
    }

    @Override
    public void render(AmbientBlockEntity be, float partialTick, PoseStack pose,
                       MultiBufferSource buffers, int light, int overlay) {
        // getDayTime() is the day cycle; getGameTime() is a raw tick counter
        long dayTime = be.getLevel() != null ? be.getLevel().getDayTime() : 0;
        var block = dayTime % 24000 < 12000
                ? Blocks.HAY_BLOCK : Blocks.BLUE_WOOL;
        pose.pushPose();
        pose.translate(0.5, 0.2, 0.5);
        pose.scale(0.6f, 0.6f, 0.6f);
        ctx.getBlockRenderDispatcher().getBlockRenderer().renderSingleBlock(
                block.defaultBlockState(), pose, buffers, light,
                OverlayTexture.NO_OVERLAY);
        pose.popPose();
