import com.mojang.math.Axis;
import com.example.examplemod.block.entity.TrophyBlockEntity;

public class TrophyBER implements BlockEntityRenderer<TrophyBlockEntity> {
    private static final int BUDGET = 12;
    private final BlockEntityRendererProvider.Context ctx;

    public TrophyBER(BlockEntityRendererProvider.Context ctx) {
        this.ctx = ctx;
    }

    @Override
    public void render(TrophyBlockEntity be, float partialTick, PoseStack pose,
                       MultiBufferSource buffers, int light, int overlay) {
        int count = Math.min(be.getItemCount(), BUDGET);
        ItemStack trophy = new ItemStack(Items.EMERALD);
        for (int i = 0; i < count; i++) {
            double a = Math.toRadians(i * (360.0 / BUDGET));
            pose.pushPose();
