    public ResourceLocation getTextureLocation(Marker entity) {
        return ResourceLocation.withDefaultNamespace("textures/misc/white.png");
    }

    @Override
    public void render(Marker entity, float entityYaw, PoseStack pose,
                       MultiBufferSource buffers, int light) {
        var cam = Minecraft.getInstance().gameRenderer.getMainCamera().getPosition();
        double dx = cam.x - entity.getX();
        double dy = cam.y - entity.getY();
        double dz = cam.z - entity.getZ();
