import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.blaze3d.vertex.VertexConsumer;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.RenderType;
import net.minecraft.client.renderer.entity.EntityRenderer;
import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.Mth;
import org.joml.Matrix3f;
import org.joml.Quaternionf;
import org.joml.Vector3f;
import com.example.examplemod.entity.Boss;

public class HealthbarEntityRenderer extends EntityRenderer<Boss> {
    public HealthbarEntityRenderer(EntityRendererProvider.Context ctx) {
        super(ctx);
    }

    @Override
    public ResourceLocation getTextureLocation(Boss entity) {
        return ResourceLocation.withDefaultNamespace("textures/misc/white.png");
    }

    @Override
    public void render(Boss entity, float entityYaw, PoseStack pose,
                       MultiBufferSource buffers, int light) {
        super.render(entity, entityYaw, pose, buffers, light);
        Quaternionf cam = Minecraft.getInstance().getEntityRenderDispatcher()
                .cameraOrientation();
        pose.pushPose();
        pose.translate(0, entity.getBbHeight() + 0.4, 0);
        pose.mulPose(cam);
        float ratio = Mth.clamp(entity.getHealth() / entity.getMaxHealth(), 0f, 1f);
        VertexConsumer vc = buffers.getBuffer(RenderType.gui());
        Matrix3f normal = pose.last().normal();
        Vector3f n = new Vector3f(0, 0, 1);
        n.normalize();
        quad(vc, pose, -0.45f, 0, -0.45f, 0.12f, 0x88_202020, normal, n, 0.0f);
        quad(vc, pose, -0.45f, 0, -0.45f + 0.9f * ratio, 0.12f,
                0x88_44DD44, normal, n, 0.005f);
        pose.popPose();
    }

    private void quad(VertexConsumer vc, PoseStack pose,
                      float x, float y, float w, float h, int argb,
                      Matrix3f normal, Vector3f n, float z) {
        var poseT = pose.last().pose();
        float a = (argb >>> 24) & 0xFF, r = (argb >>> 16) & 0xFF,
              g = (argb >>> 8) & 0xFF, b = argb & 0xFF;
        float[][] pts = {{x, y, z}, {x + w, y, z}, {x + w, y + h, z}, {x, y + h, z}};
        for (float[] p : pts) {
            var v = vc.addVertex(poseT, p[0], p[1], p[2]);
            v.setColor((int) r, (int) g, (int) b, (int) a);
            v.setNormal(normal, n.x, n.y, n.z);
        }
    }
}

package com.example.examplemod.client.render;

import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.blaze3d.vertex.VertexConsumer;
import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.RenderType;
import net.minecraft.client.renderer.entity.EntityRenderer;
import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.resources.ResourceLocation;
import org.joml.Matrix3f;
import org.joml.Vector3f;
import com.example.examplemod.entity.TeamCube;

public class TeamColorCubeRenderer extends EntityRenderer<TeamCube> {
    private static final ResourceLocation TEXTURE =
            ResourceLocation.withDefaultNamespace("textures/block/white_concrete.png");

    public TeamColorCubeRenderer(EntityRendererProvider.Context ctx) {
        super(ctx);
    }

    public static int shade(int argb, float factor) {
        int a = (argb >>> 24) & 0xFF;
        int r = Math.min(255, (int) (((argb >>> 16) & 0xFF) * factor));
        int g = Math.min(255, (int) (((argb >>> 8) & 0xFF) * factor));
        int b = Math.min(255, (int) ((argb & 0xFF) * factor));
        return (a << 24) | (r << 16) | (g << 8) | b;
    }

    @Override
    public ResourceLocation getTextureLocation(TeamCube entity) {
        return TEXTURE;
    }

    @Override
    public void render(TeamCube entity, float entityYaw, PoseStack pose,
                       MultiBufferSource buffers, int light) {
        int team = entity.getTeamColor();
        VertexConsumer vc = buffers.getBuffer(RenderType.entitySolid(TEXTURE));
        Matrix3f normal = pose.last().normal();
        Vector3f n = new Vector3f(0, 1, 0).normalize();
        pose.pushPose();
        pose.translate(0.5, 0.5, 0.5);
        pose.scale(0.3f, 0.3f, 0.3f);
        var m = pose.last().pose();
        float[][] c = {{-0.5f, 0.5f, -0.5f}, {0.5f, 0.5f, -0.5f},
                       {0.5f, 0.5f, 0.5f}, {-0.5f, 0.5f, 0.5f}};
        int color = shade(team, 1.0f);
        int a = (color >>> 24) & 0xFF, r = (color >>> 16) & 0xFF,
            g = (color >>> 8) & 0xFF, b = color & 0xFF;
        for (float[] p : c) {
            var v = vc.addVertex(m, p[0], p[1], p[2]);
            v.setColor(r, g, b, a == 0 ? 255 : a);
            v.setNormal(normal, n.x, n.y, n.z);
        }
        pose.popPose();
        super.render(entity, entityYaw, pose, buffers, light);
    }
}

