package com.example.examplemod.client;

import net.minecraft.client.gui.Font;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.world.item.ItemStack;

public class BerItemPulseHandler {
    public static void renderItemsInGui(GuiGraphics g, Font font,
                                        ItemStack[] stacks, int x0, int y0,
                                        int cell) {
        int shown = 0;
        for (int i = 0; i < stacks.length && shown < 8; i++) {
            ItemStack s = stacks[i];
            int x = x0 + i * cell;
            if (!s.isEmpty()) {
                g.renderItem(s, x, y0);
                g.renderItemDecorations(font, s, x, y0);
            }
            shown++;
        }
        int overflow = stacks.length - 8;
        if (overflow > 0) {
            g.drawString(font, "+" + overflow, x0 + 7 * cell + 2, y0 + 8, 0xFFFF55);
        }
    }
}

package com.example.examplemod.client.render;

import net.minecraft.client.renderer.LightTexture;

public class LightDecode {
    public static String describe(int packedLight) {
        if (packedLight == 15728880) return "bright";
        int b = LightTexture.block(packedLight);
        int s = LightTexture.sky(packedLight);
        if (b == 0 && s == 0) return "dark";
        return "block=" + b + ",sky=" + s;
    }

    public static int packOrBright(int block, int sky) {
        block = MthClamp(block);
        sky = MthClamp(sky);
        return LightTexture.pack(block, sky);
    }

    private static int MthClamp(int v) {
        return Math.max(0, Math.min(15, v));
    }
}

