package com.example.examplemod.client.render;

public class CameraRelDoc {
    public static double[] toCameraRelative(double wx, double wy, double wz,
                                            double camX, double camY, double camZ) {
        return new double[]{wx - camX, wy - camY, wz - camZ};
    }

    public static boolean isBehindPlane(double[] rel, double[] planeNormal,
                                        double planeD) {
        double len2 = planeNormal[0] * planeNormal[0]
                + planeNormal[1] * planeNormal[1]
                + planeNormal[2] * planeNormal[2];
        if (len2 == 0) return false;
        double dot = rel[0] * planeNormal[0] + rel[1] * planeNormal[1]
                + rel[2] * planeNormal[2];
        return dot + planeD < 0;
    }
}

package com.example.examplemod.client.render;

import java.util.LinkedHashMap;

public class RenderOrderDoc {
    // LinkedHashMap keeps insertion order: this map IS the documented order
    public static final LinkedHashMap<String, Integer> LAYER_ORDER =
            new LinkedHashMap<>();

    static {
        LAYER_ORDER.put("opaque", 0);
        LAYER_ORDER.put("cutout", 1);
        LAYER_ORDER.put("translucent", 2);
        LAYER_ORDER.put("glow", 3);
        LAYER_ORDER.put("overlay", 4);
    }

    public static boolean isTranslucentRenderedBeforeGlow() {
        return LAYER_ORDER.get("translucent") < LAYER_ORDER.get("glow");
    }
}

