                       MultiBufferSource buffers, int light, int overlay) {
        long t = be.getLevel() != null ? be.getLevel().getGameTime() : 0;
        // translucent look comes from the GLASS model; forcing translucent buffers
        // for opaque geometry would create sorting artifacts
        float scale = Mth.clamp(0.8f + (float) Math.sin(t * 0.08) * 0.05f,
                0.75f, 0.85f);
        pose.pushPose();
        pose.translate(0.5, 0.5, 0.5);
        pose.scale(scale, scale, scale);
        ctx.getBlockRenderDispatcher().getBlockRenderer().renderSingleBlock(
                Blocks.GLASS.defaultBlockState(), pose, buffers, light,
                OverlayTexture.NO_OVERLAY);
        pose.popPose();
    }
}

package com.example.examplemod.client.render;

import net.minecraft.client.renderer.LightTexture;
import net.minecraft.util.Mth;

public class EmissiveLightCalc {
    public static float lerpIntToFloat(int a, int b, float t) {
        return Mth.lerp(t, a, b);
    }

    public static int emissiveLight(int worldLight, float glowLevel) {
        float g = Mth.clamp(glowLevel, 0.0f, 1.0f);
        int worldBlock = LightTexture.block(worldLight);
        int worldSky = LightTexture.sky(worldLight);
        int blockLight = Math.round(lerpIntToFloat(worldBlock, 15, g));
        int skyLight = Math.round(lerpIntToFloat(worldSky, 15, g));
        blockLight = Mth.clamp(blockLight, 0, 15);
        skyLight = Mth.clamp(skyLight, 0, 15);
        return LightTexture.pack(blockLight, skyLight);
    }
}

package com.example.examplemod.client.render;

import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.blockentity.BlockEntityRenderer;
import net.minecraft.client.renderer.blockentity.BlockEntityRendererProvider;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.util.Mth;
import net.minecraft.world.level.block.Blocks;

import com.mojang.blaze3d.vertex.PoseStack;
import com.example.examplemod.block.entity.CauldronFillBlockEntity;

public class CauldronFillBER implements BlockEntityRenderer<CauldronFillBlockEntity> {
    private final BlockEntityRendererProvider.Context ctx;

    public CauldronFillBER(BlockEntityRendererProvider.Context ctx) {
        this.ctx = ctx;
    }

    @Override
    public void render(CauldronFillBlockEntity be, float partialTick, PoseStack pose,
                       MultiBufferSource buffers, int light, int overlay) {
        float fill = Mth.clamp(be.getFillLevel(), 0.0f, 1.0f);
        if (fill <= 0.0f) return;
        // anchor at the column base so scale grows upward
        pose.pushPose();
        pose.translate(0.5, 0.15, 0.5);
        pose.scale(0.8f, fill * 0.7f, 0.8f);
        ctx.getBlockRenderDispatcher().getBlockRenderer().renderSingleBlock(
                Blocks.LIGHT_BLUE_STAINED_GLASS.defaultBlockState(), pose,
                buffers, light, OverlayTexture.NO_OVERLAY);
        pose.popPose();
    }
}

package com.example.examplemod.client.render;

import com.mojang.math.Axis;
import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.blockentity.BlockEntityRenderer;
import net.minecraft.client.renderer.blockentity.BlockEntityRendererProvider;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.world.level.block.Blocks;

import com.mojang.blaze3d.vertex.PoseStack;
import com.example.examplemod.block.entity.PortalRingBlockEntity;

public class PortalRingBER implements BlockEntityRenderer<PortalRingBlockEntity> {
    private final BlockEntityRendererProvider.Context ctx;

    public PortalRingBER(BlockEntityRendererProvider.Context ctx) {
        this.ctx = ctx;
    }

    @Override
    public void render(PortalRingBlockEntity be, float partialTick, PoseStack pose,
                       MultiBufferSource buffers, int light, int overlay) {
        long t = be.getLevel() != null ? be.getLevel().getGameTime() : 0;
        // far/translucent halo first, opaque core second (back-to-front)
        pose.pushPose();
        pose.translate(0.5, 0.5, 0.5);
        pose.mulPose(Axis.YP.rotationDegrees(t * 0.5f));
        pose.scale(0.9f, 0.9f, 0.9f);
        ctx.getBlockRenderDispatcher().getBlockRenderer().renderSingleBlock(
                Blocks.GLASS.defaultBlockState(), pose, buffers, light,
                OverlayTexture.NO_OVERLAY);
        pose.popPose();
        pose.pushPose();
        pose.translate(0.5, 0.5, 0.5);
        pose.scale(0.6f, 0.6f, 0.6f);
        ctx.getBlockRenderDispatcher().getBlockRenderer().renderSingleBlock(
                Blocks.CRYING_OBSIDIAN.defaultBlockState(), pose, buffers,
                light, OverlayTexture.NO_OVERLAY);
        pose.popPose();
    }
}

