package com.example.examplemod.particle;

import net.minecraft.world.level.Level;

public class SpawnPuffEffect {
    // client-only: server-side addParticle is a no-op there
    public static void spawn(Level level, double x, double y, double z, int count) {
        if (!level.isClientSide) return;
        for (int i = 0; i < count; i++) {
            level.addParticle(ModParticles.MYST_SPARK.get(),
                    x, y, z,
                    level.random.nextDouble() * 0.1 - 0.05,
                    level.random.nextDouble() * 0.1,
                    level.random.nextDouble() * 0.1 - 0.05);
        }
    }
}

