import java.util.concurrent.Executor;

@OnlyIn(Dist.CLIENT)
public class ResourceReloadHook {
    public static final ReloadAwareCache<String, String> MODEL_CACHE =
            new ReloadAwareCache<>();

    public static void onClientReload(RegisterClientReloadListenersEvent event) {
        event.registerListener(new ResourceManagerReloadListener() {
            @Override
            protected void apply(ResourceManager manager, Executor executor) {
                MODEL_CACHE.invalidateAll();
            }
        });
    }
}

